// YouTube OAuth — Exchange authorisation code for access + refresh tokens
// Google OAuth 2.0 with offline access gives a refresh token for long-term use
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME
// Required env vars: YOUTUBE_CLIENT_ID, YOUTUBE_CLIENT_SECRET

const body = $input.first().json.body || $input.first().json;
const code        = body.code;
const memberEmail = body.member_email || '';
const redirectUri = body.redirect_uri || 'https://brief.one-empire.com/youtube/callback';

if (!code) {
  throw new Error('Missing authorisation code');
}

const clientId     = $env.YOUTUBE_CLIENT_ID;
const clientSecret = $env.YOUTUBE_CLIENT_SECRET;

// Exchange code for tokens
const tokenParams = new URLSearchParams({
  code:          code,
  client_id:     clientId,
  client_secret: clientSecret,
  redirect_uri:  redirectUri,
  grant_type:    'authorization_code'
});

let tokenData;
try {
  const tokenRes = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://oauth2.googleapis.com/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: tokenParams.toString()
  });
  tokenData = typeof tokenRes === 'string' ? JSON.parse(tokenRes) : tokenRes;
} catch (e) {
  throw new Error('Google token exchange failed: ' + e.message);
}

if (tokenData.error) {
  throw new Error('Google error: ' + (tokenData.error_description || tokenData.error));
}

const accessToken  = tokenData.access_token;
const refreshToken = tokenData.refresh_token || null;
const expiresIn    = tokenData.expires_in || 3600;

// Fetch YouTube channel info
let channelId   = '';
let channelName = '';
try {
  const channelRes = await $helpers.httpRequest({
    method: 'GET',
    url: `https://www.googleapis.com/youtube/v3/channels?part=snippet&mine=true&access_token=${accessToken}`
  });
  const channelData = typeof channelRes === 'string' ? JSON.parse(channelRes) : channelRes;
  if (channelData.items && channelData.items.length > 0) {
    channelId   = channelData.items[0].id || '';
    channelName = channelData.items[0].snippet?.title || '';
  }
} catch (e) {
  // Non-fatal
}

const now      = new Date();
const expiresAt = new Date(now.getTime() + expiresIn * 1000);

return [{
  json: {
    member_email:     memberEmail,
    youtube_id:       channelId,
    youtube_name:     channelName,
    access_token:     accessToken,
    refresh_token:    refreshToken,
    expires_in:       expiresIn,
    token_stored_at:  now.toISOString(),
    token_expires_at: expiresAt.toISOString(),
    is_active:        true
  }
}];

// Store YouTube token in Supabase
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME

const data = $input.first().json;
const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

if (!data.member_email) {
  throw new Error('member_email is required');
}

const payload = {
  member_email:     data.member_email,
  youtube_id:       data.youtube_id,
  youtube_name:     data.youtube_name,
  access_token:     data.access_token,
  refresh_token:    data.refresh_token,
  expires_in:       data.expires_in,
  token_stored_at:  data.token_stored_at,
  token_expires_at: data.token_expires_at,
  is_active:        true
};

try {
  await $helpers.httpRequest({
    method: 'POST',
    url: `${supabaseUrl}/rest/v1/youtube_tokens`,
    headers: {
      'Content-Type':  'application/json',
      'apikey':        serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
      'Prefer':        'resolution=merge-duplicates'
    },
    body: JSON.stringify(payload)
  });
  return [{ json: { success: true, message: 'YouTube token stored', member_email: data.member_email } }];
} catch (e) {
  throw new Error('Failed to store YouTube token: ' + e.message);
}
